import fs from 'fs';
import path from 'path';
import { TEXT_ROLES } from '@/lib/brand/tokens.generated';

/**
 * Colours live only in web_client/brand/tokens and reach code through the semantic
 * roles (bg-canvas, text-ink, ...) and the generated files. The rest of the frontend
 * must not write a colour literal of its own, nor put opacity on a text role (its
 * contrast is validated in build only at full strength).
 *
 * Generated files declare themselves with the pipeline header, so the exclusion list
 * is never written by hand: a new generated file is skipped as soon as it exists.
 */
const webRoot = path.resolve(__dirname, '..');

const GUARDED = ['app', 'components', 'lib', 'hooks'];
const GENERATED_HEADER = /GENERATED by scripts\/brand\//;
const COLOR_LITERAL = /#[0-9a-f]{3,8}\b|\b(?:rgba?|hsla?|oklch|oklab|lab|lch|hwb)\(/i;
// Built from the generated roles: a text role added later is covered with no edit here.
// Numeric (/60) and arbitrary (/[0.4], /[40%]) opacity alike.
// `outline-none` removes the outline outright; the ring utilities that replace it are a
// box-shadow, which forced-colors mode (Windows high contrast) drops, leaving no focus
// indicator at all. `outline-hidden` keeps a transparent outline that mode makes visible.
const OUTLINE_NONE = /(?<![\w-])(?:[\w-]+:)*outline-none(?![\w-])/;
const TEXT_ROLE_OPACITY = new RegExp(
    `(?<![\\w-])(?:[\\w-]+:)*text-(?:${TEXT_ROLES.join('|')})\\/(?:\\d+|\\[[^\\]\\s]+\\])`,
);

function files(entry: string): string[] {
    const full = path.join(webRoot, entry);
    if (fs.statSync(full).isFile()) return [full];
    return fs
        .readdirSync(full, { withFileTypes: true })
        .filter((e) => e.name !== '__tests__')
        .flatMap((e) => (e.isDirectory() ? files(path.join(entry, e.name)) : [path.join(full, e.name)]))
        .filter((f) => /\.(ts|tsx|css)$/.test(f));
}

const sources = GUARDED.flatMap(files)
    .map((f) => ({ f, rel: path.relative(webRoot, f).replaceAll('\\', '/'), text: fs.readFileSync(f, 'utf8') }))
    .filter(({ text }) => !GENERATED_HEADER.test(text.slice(0, 400)));

/**
 * Comments paint nothing, and `#133` there is an issue reference, not a colour.
 * Blank out comment text only (line breaks kept, so line numbers stay right): code before
 * or after a comment on the same line is still checked. `//` counts only at a line start
 * or after whitespace, so a URL (https://) is not a comment.
 */
function stripComments(text: string): string {
    return text
        .replace(/\/\*[\s\S]*?\*\//g, (c) => c.replace(/[^\n]/g, ' '))
        .replace(/(^|\s)\/\/.*$/gm, '$1');
}

function offending(text: string, pattern: RegExp): string[] {
    const code = stripComments(text).split('\n');
    return text
        .split('\n')
        .map((line, i) => [i + 1, line] as const)
        .filter(([n]) => pattern.test(code[n - 1]))
        .map(([n, line]) => `${n}: ${line.trim()}`);
}

describe('guard patterns', () => {
    it('catch numeric and arbitrary opacity on text roles', () => {
        for (const cls of ['text-ink/60', 'text-ink/[0.4]', 'hover:text-ink-muted/[50%]']) {
            expect(offending(cls, TEXT_ROLE_OPACITY)).toHaveLength(1);
        }
        expect(offending('text-ink bg-canvas/80', TEXT_ROLE_OPACITY)).toEqual([]);
    });

    it('skip comments but not code that merely starts with * or follows a comment', () => {
        expect(offending('// see #133\n/* issue #125 */\n/**\n * PR #566\n */', COLOR_LITERAL)).toEqual([]);
        expect(offending('* { outline-color: #ff0000; }', COLOR_LITERAL)).toHaveLength(1);
        expect(offending('/* fallback */ background: rgba(0, 0, 0, 0.5);', COLOR_LITERAL)).toHaveLength(1);
        expect(offending('/* a\n   #123 b */\ncolor: #123;', COLOR_LITERAL)).toEqual(['3: color: #123;']);
    });
});

describe('no hard-coded colours in the frontend', () => {
    it.each(sources.map((s) => [s.rel, s.text]))('%s', (_rel, text) => {
        expect(offending(text, COLOR_LITERAL)).toEqual([]);
    });
});

describe('no opacity modifier on text roles', () => {
    it.each(sources.map((s) => [s.rel, s.text]))('%s', (_rel, text) => {
        expect(offending(text, TEXT_ROLE_OPACITY)).toEqual([]);
    });
});

describe('focus outlines survive forced-colors mode', () => {
    it.each(sources.map((s) => [s.rel, s.text]))('%s', (_rel, text) => {
        expect(offending(text, OUTLINE_NONE)).toEqual([]);
    });
});
